cd /workspace && python3 - <<'PY'
import json,subprocess,sys,random
MAIN='submission/main.py'
def run_raw(data):
    p=subprocess.run([sys.executable,'-I','-B',MAIN],input=data,capture_output=True)
    return p.returncode,p.stdout,p.stderr
random.seed(7)
def rnd(depth=0):
    choices=['int','str','bool','none','list','dict']
    c=random.choice(choices if depth<3 else ['int','str','none'])
    if c=='int': return random.choice([0,1,-1,2,10,100000000000000000000, 1.5, True])
    if c=='bool': return random.choice([True,False])
    if c=='str': return random.choice(['','x','sip:a@b.test','e','alice','\u00e9'])
    if c=='none': return None
    if c=='list': return [rnd(depth+1) for _ in range(random.randint(0,3))]
    if c=='dict':
        d={}
        for _ in range(random.randint(0,4)):
            k=random.choice(['version','config','events','accounts','peers','ttl_ms','capacity','id','default','aliases','mode','t','peer','auth','egress','wire_hex'])
            d[k]=rnd(depth+1)
        return d
bad=0
for _ in range(2000):
    obj=rnd()
    data=json.dumps(obj).encode()
    rc,out,err=run_raw(data)
    if rc not in (0,2):
        bad+=1; print('BAD rc',rc,repr(data)[:120], err[:200]); break
print('envelope fuzz bad=',bad)
